export const projects=[
 {id:'signal',category:'growth',year:'2023–2025',tone:'sage',name:'Signal',content:{
 en:{type:'GROWTH & ANALYTICS',title:'A clearer signal. A better next move.',short:'Signal — the growth workspace',preview:'From scattered channel reports to one decision-ready view. Switch markets, inspect sales and orders, and model a budget scenario.',summary:'A fictional commerce team needed a way to see what was working across three markets — without mistaking a bigger number for a better decision.',role:'Growth strategy, metric definitions, information architecture and interaction design.',question:'How might a small team move from reporting numbers to making a focused weekly growth decision?',facts:[['Markets','US · UK · DE'],['Dataset','28 sample days'],['Units','USD · orders']],challenge:'Every channel told a different story. The useful question was not “which chart looks best?”, but “where is the next constraint, and what evidence would change our mind?”',decisions:[['Give every number a context','Market and time controls update the whole report together. Spend, attributed revenue and orders share a visible period; ROAS is revenue divided by spend.'],['Keep forecasts separate from observations','The budget slider produces an illustrative scenario using a stated constant-ROAS assumption. It never changes the historical dataset or pretends to predict reality.'],['Let people inspect the details','An accessible chart summary, the product summary table and daily CSV export make the sample report inspectable. A dashboard is useful when its summary can be traced back.']],outcome:'This working browser demo shows coherent filtering, metric calculation and scenario modelling. The dataset is invented; it does not substantiate a real TikTok account, client result or advertising outcome.'},
 zh:{type:'增长策略与数据分析',title:'看清信号，才能选好下一步。',short:'Signal · 增长工作台',preview:'把分散的渠道报表整理成可决策的视图。切换市场、查看销售与订单，再试一组预算情景。',summary:'在这个虚构案例里，小团队需要理解三个市场的增长表现，而不只是追逐看起来更大的数字。',role:'增长策略、指标口径、信息架构与交互设计。',question:'怎样让一份报表帮助团队做出清楚的每周增长决策？',facts:[['市场','美国 · 英国 · 德国'],['数据','28 天模拟记录'],['口径','美元 · 订单']],challenge:'每个渠道都在讲不同的故事。真正有价值的问题是：当前的瓶颈在哪里，什么证据会让我们改变决定？',decisions:[['每个数字都有上下文','市场和时间筛选一起作用于整份报表。花费、归因收入与订单使用相同的可见周期，ROAS 按收入除以花费计算。'],['把观察与情景分开','预算滑块使用明确说明的恒定 ROAS 假设生成示例情景，不修改历史数据，也不伪装成真实预测。'],['让细节可以被检查','图表文字摘要、商品汇总表与每日 CSV 导出让读者追溯汇总数据。摘要背后有细节，报表才真正可用。']],outcome:'这个可操作的浏览器原型展示一致的筛选、指标计算与情景建模。数据为虚构示例，不代表真实账号、客户业绩或广告效果。'}}},
 {id:'briefly',category:'product',year:'2025–2026',tone:'lilac',name:'Briefly',content:{
 en:{type:'AI PRODUCT DESIGN',title:'Less blank-page time. More useful direction.',short:'Briefly — from detail to direction',preview:'Turn a product detail into a usable content brief. Edit the audience and tone, then build and export a structured local draft.',summary:'A product concept for small commerce teams who need a shared starting point before they write, shoot and publish content.',role:'Problem framing, workflow design, prototyping and evaluation criteria.',question:'How might a small team agree on a clear content direction before spending time on production?',facts:[['Inputs','Product · audience · tone'],['Output','Structured content brief'],['Setup','No API key']],challenge:'The initial concept asked for too much and gave too little guidance. A useful brief needs a product, a person and a purpose — not a wall of empty fields.',decisions:[['Make the first step concrete','Start with a usable example and a small set of meaningful inputs. People can see the kind of answer the workflow is designed to produce.'],['Keep the reasoning beside the output','A hook, shot list and call to action are paired with a rationale. The team can discuss why a direction fits instead of accepting polished text uncritically.'],['Be honest about the prototype','The demo transforms the inputs with local templates. It does not call an AI model. A production model would need quality evaluation, editing, recovery and cost controls.']],outcome:'The local prototype validates, builds and exports actual content in the browser. It demonstrates a product workflow; it is not evidence of model quality, measured time savings or a deployed AI service.'},
 zh:{type:'AI 产品设计',title:'从不知道写什么，到有一个清楚的方向。',short:'Briefly · 从商品到内容简报',preview:'修改商品、受众与语气，生成一份结构清楚的本地内容草稿，并直接导出。',summary:'面向小型电商团队的产品概念，让写文案、拍摄和发布之前，先有一份大家能讨论的共同起点。',role:'问题定义、流程设计、交互原型与评估标准。',question:'怎样在投入制作之前，让小团队对内容方向形成清楚的共识？',facts:[['输入','商品 · 受众 · 语气'],['输出','结构化内容简报'],['使用','无需 API 密钥']],challenge:'最初的概念要求填写很多内容，却很少提供引导。一份有用的简报，需要明确商品、受众和目的，而不只是堆满输入框。',decisions:[['让第一步具体可见','提供可修改的示例与少量有意义的输入，让使用者理解这个流程能产出什么。'],['把理由放在输出旁边','开头、镜头清单与行动引导都有相应理由，团队可以讨论方向是否合适。'],['说清原型真正做了什么','演示使用本地模板转换输入，不调用 AI 模型。真正接入模型时，还需要质量评估、编辑、恢复与成本控制。']],outcome:'这个本地原型会在浏览器里实际校验输入、生成内容并导出。它展示产品流程，不代表模型质量、量化提效或已经上线的 AI 服务。'}}},
 {id:'fieldwork',category:'research',year:'2026',tone:'sand',name:'Fieldwork',content:{
 en:{type:'RESEARCH & PRODUCT STRATEGY',title:'Build the right small thing first.',short:'Fieldwork — research into a roadmap',preview:'Follow a research synthesis from recurring friction to a focused MVP. Compare three concepts and inspect the trade-offs.',summary:'An illustrative research exercise about helping small commerce teams turn weekly learning into their next product decision.',role:'Research planning, synthesis, concept comparison and MVP scope.',question:'What would we build first if we cared about learning speed as much as feature count?',facts:[['Research','6 fictional interviews'],['Exploration','3 concepts'],['Decision','1 focused MVP']],challenge:'A long feature list made the opportunity feel bigger, but made the first useful release harder to see. The research needed to lead to a choice.',decisions:[['Group by the decision people need to make','Sample notes are organised around recurring questions, workarounds and consequences. Every finding is labelled illustrative, not presented as real interview evidence.'],['Make trade-offs explicit','Compare a report hub, a decision brief and a full automation suite using effort, value and learning speed. The chosen concept keeps the first release small and inspectable.'],['Choose the next test before the next feature','A next-step plan names the behaviour to observe and what would change the direction. No fabricated success percentage is needed to explain a defensible choice.']],outcome:'This case demonstrates research structure and product judgement using invented material. It does not claim real interviews, real users or measured product-market fit.'},
 zh:{type:'用户研究与产品策略',title:'先做小一点，也做对一点。',short:'Fieldwork · 从研究到产品路线',preview:'从反复出现的问题走向一个清楚的 MVP。比较三种概念，看看每一步怎样做取舍。',summary:'一个关于小型电商团队的示例研究：怎样把每周学到的东西，转化为下一步产品决定。',role:'研究计划、问题归纳、概念比较与 MVP 范围。',question:'如果同样重视学习速度与功能数量，我们会先做什么？',facts:[['研究','6 份虚构访谈'],['探索','3 个产品概念'],['决定','1 个聚焦 MVP']],challenge:'很长的功能清单让机会显得很大，却让第一个有用的版本越来越模糊。研究最终需要帮助团队做出一个选择。',decisions:[['围绕用户要做的决定来归纳','示例笔记按反复出现的问题、现有做法与影响组织；所有内容标注为示意材料，不包装成真实访谈证据。'],['让取舍看得见','比较报表中心、决策简报与全自动系统的投入、价值和学习速度，让第一个版本足够小，也足够可检查。'],['先决定下个验证，再增加功能','说明下一步观察什么行为，以及什么结果会让团队改变方向，不用虚构成功率来支持判断。']],outcome:'这个案例用虚构材料展示研究组织与产品判断，不声称进行过真实访谈、拥有真实用户或已经验证产品市场匹配。'}}}
];
export const localProject=(p,lang)=>({...p,...p.content[lang]});
